class Solution {
  public int[] minOperations(int[] nums) {
    List<Integer> pals = new ArrayList<>();
    for (int x = 0; x < 16384; x++) {
      String b = Integer.toBinaryString(x);
      if (new StringBuilder(b).reverse().toString().equals(b)) pals.add(x);
    }
    int[] ans = new int[nums.length];
    for (int i = 0; i < nums.length; i++) {
      int best = Integer.MAX_VALUE;
      for (int p : pals) best = Math.min(best, Math.abs(p - nums[i]));
      ans[i] = best;
    }
    return ans;
  }
}
